args.command:
cd out && python3 - <<'EOF'
import openpyxl, csv, glob, os
wb=openpyxl.load_workbook('交接.xlsx')

# 期初: from 在用登记 (05-31)
rows=[]
for p in sorted(glob.glob('../input/客户档案/*/在用/*.md')):
    d={}
    for line in open(p,encoding='utf-8'):
        if '：' in line:
            k,v=line.strip().split('：',1)
            d[k.strip()]=v.strip()
    rows.append((d['对象'], d['版号'], d['登记日']))
rows.sort()
print(len(rows), rows)
ws=wb['期初']
# clear old data rows
if ws.max_row>1: ws.delete_rows(2, ws.max_row-1)
for o,v,_ in rows: ws.append([o,v])

# 待办: from 上班遗留.csv, status unchanged as of 6月1日 (no new receipts/inbox)
ws=wb['待办']
if ws.max_row>1: ws.delete_rows(2, ws.max_row-1)
for r in csv.DictReader(open('../input/办公室/上班遗留.csv',encoding='utf-8')):
    ws.append([r['案号'], r['状态'], r['下一步']])

wb.save('交接.xlsx')
wb2=openpyxl.load_workbook('交接.xlsx')
for ws in wb2.worksheets[:2]:
    print('==',ws.title)
    for r in ws.iter_rows(values_only=True): print(r)
EOF
